public class E305 {
    interface Logger {
        void log(String s);
        default void logErr(String s){ log("ERR: " + s); }
    }
    static class ConsoleLogger implements Logger {
        public void log(String s){ System.out.println(s); }
    }
    public static void main(String[] args) {
        Logger l = new ConsoleLogger();
        l.log("hello");
        l.logErr("boom");
    }
}
